INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '63079098', 'CN', 7.5, 'ad_valorem', 'Section 301, China, List 4A (described items): HTSUS heading 9903.88.15, U.S. note 20(s)(ii) to subchapter III of chapter 99; 7.5% additional ad valorem (HTS 2026 Rev. 23)', '2020-02-14', NULL, '["REVIEW: Heading 9903.88.15 covers only part of this 8-digit line (all except respirators (6307.90.9842, .9844, .9850) and face masks (6307.90.9870, .9875)). Which duty applies depends on the 10-digit statistical suffix, which this app does not hold. Check U.S. note 20(s)(ii)."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
