INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '63079098', 'CN', 50, 'ad_valorem', 'Section 301, China, four-year review increase: HTSUS heading 9903.91.07, U.S. note 31(h) to subchapter III of chapter 99; 50% additional ad valorem from 2026-01-01 (HTS 2026 Rev. 23)', '2026-01-01', NULL, '["REVIEW: Heading 9903.91.07 covers only these statistical numbers under this 8-digit line: 6307.90.9842, .9844 (N95 respirators), .9850 (other respirators) and .9870, .9875 (face masks). Which duty applies depends on the 10-digit suffix, which this app does not hold. Check U.S. note 31(h)."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '84261900', 'CN', 25, 'ad_valorem', 'Section 301, China, cranes: HTSUS heading 9903.92.10 (+25%, ship-to-shore gantry cranes), with 9903.91.09 and 9903.91.14 to 9903.91.16, U.S. note 31 to subchapter III of chapter 99 (HTS 2026 Rev. 23)', '2024-09-27', NULL, '["REVIEW: Cranes of heading 8426.19.00 are covered only if they are ship-to-shore gantry cranes (9903.92.10, plus 25 percent; 9903.91.09 exempts those fulfilling certain pre-2024 contracts; from 2027-01-10 9903.91.14 adds 100 percent unless 9903.91.15 or .16 is claimed). Whether this good is one cannot be read from the HTS code. Check U.S. note 31(l) and the headings named."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '87169030', 'CN', 100, 'ad_valorem', 'Section 301, China, intermodal chassis: HTSUS heading 9903.91.12, U.S. note 31(k) to subchapter III of chapter 99; 100% additional ad valorem on entries on or after 2027-01-10 (HTS 2026 Rev. 23)', '2027-01-10', NULL, '["REVIEW: Heading 9903.91.12 (from 2027-01-10) covers intermodal chassis, their subassemblies and parts; other goods of this line are under 9903.91.13 at no additional duty. Whether this good is one cannot be read from the HTS code. Check U.S. note 31(k)."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '87169050', 'CN', 100, 'ad_valorem', 'Section 301, China, intermodal chassis: HTSUS heading 9903.91.12, U.S. note 31(k) to subchapter III of chapter 99; 100% additional ad valorem on entries on or after 2027-01-10 (HTS 2026 Rev. 23)', '2027-01-10', NULL, '["REVIEW: Heading 9903.91.12 (from 2027-01-10) covers intermodal chassis, their subassemblies and parts; other goods of this line are under 9903.91.13 at no additional duty. Whether this good is one cannot be read from the HTS code. Check U.S. note 31(k)."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china', '87163900', 'CN', 100, 'ad_valorem', 'Section 301, China, intermodal chassis: HTSUS heading 9903.91.12, U.S. note 31(k) to subchapter III of chapter 99; 100% additional ad valorem on entries on or after 2027-01-10 (HTS 2026 Rev. 23)', '2027-01-10', NULL, '["REVIEW: Heading 9903.91.12 (from 2027-01-10) covers only statistical number 8716.39.0090 under this line, when it is an intermodal chassis, subassembly or part. Which duty applies depends on the 10-digit suffix and the good, which this app does not hold. Check U.S. note 31(k)."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
